sub is_test_file {
    my ($path) = @_;
    return $path =~ /_test\.go$/;
}

sub pkg_path_from_file {
    my ($file) = @_;
    my $dir = dirname($file);
    $dir =~ s/^\Q$REPO\E\/?//;
    return $dir eq '' ? $MODULE : "$MODULE/$dir";
}

my %decls;
my @decl_order;

sub decl_key {
    my ($pkg_path, $recv, $name) = @_;
    $recv //= '';
    return "$pkg_path|$recv|$name";
}

sub parse_internal_decls {
    find({
        wanted => sub {
            return unless $_ =~ /\.go$/;
            return unless $File::Find::name =~ m{^\Q$REPO\E/internal/};
            my $file = $File::Find::name;
            open my $fh, '<', $file or return;
            local $/;
            my $raw = <$fh>;
            close $fh;

            my $pkg = 'unknown';
            if ($raw =~ /^package\s+(\w+)/m) {
                $pkg = $1;
            }
            my $pkg_path = pkg_path_from_file($file);
            my @lines = split /\n/, $raw;
            for my $ln (0 .. $#lines) {
                my $line = $lines[$ln];
                next unless $line =~ /^\s*func\s+/;
                my ($recv, $name);
                if ($line =~ /^\s*func\s+\(([^)]*)\)\s+(\w+)\s*[\(<]/) {
                    ($recv, $name) = ($1, $2);
                    $recv =~ s/^\s+|\s+$//g;
                    if ($recv =~ /\*\s*([\w\.]+)\s*$/) {
                        $recv = $1;
                    } elsif ($recv =~ /([\w\.]+)\s*$/) {
                        $recv = $1;
                    }
                } elsif ($line =~ /^\s*func\s+(\w+)\s*[\(<]/) {
                    $name = $1;
                    $recv = '';
                } else {
                    next;
                }
                my $key = decl_key($pkg_path, $recv, $name);
                my $id = "$file:$name";
                $id = "$file:($recv).$name" if $recv ne '';
                $decls{$key} = {
                    name     => $name,
                    recv     => $recv,
                    pkg      => $pkg,
                    pkg_path => $pkg_path,
                    file     => $file,
                    line     => $ln + 1,
                    id       => $id,
                };
                push @decl_order, $key;
            }
        },
        no_chdir => 1,
    }, "$REPO/internal");
}

sub parse_imports {
    my ($raw) = @_;
    my %imports;
    my %path_to_aliases;

    while ($raw =~ /import\s+"([^"]+)"/g) {
        my $path = $1;
        my $alias = basename($path);
        $alias =~ s/-//g;
        $imports{$alias} = $path;
        push @{ $path_to_aliases{$path} }, $alias;
    }
    while ($raw =~ /import\s*\((.*?)\)/sg) {
        my $block = $1;
        for my $line (split /\n/, $block) {
            $line =~ s/\/\/.*$//;
            next if $line =~ /^\s*$/;
            if ($line =~ /^\s*([\w\.]+)\s+"([^"]+)"/) {
                my ($alias, $path) = ($1, $2);
                $imports{$alias} = $path;
                push @{ $path_to_aliases{$path} }, $alias;
            } elsif ($line =~ /^\s*"([^"]+)"/) {
                my $path = $1;
                my $alias = basename($path);
                $alias =~ s/-//g;
                $imports{$alias} = $path;
                push @{ $path_to_aliases{$path} }, $alias;
            }
        }
    }
    return (\%imports, \%path_to_aliases);
}

sub find_enclosing_func {
    my ($lines, $line_idx) = @_;
    for (my $i = $line_idx; $i >= 0; $i--) {
        my $l = $lines[$i];
        if ($l =~ /^\s*func\s+\(([^)]*)\)\s+(\w+)\s*[\(<]/) {
            my ($recv, $name) = ($1, $2);
            $recv =~ s/^\s+|\s+$//g;
            if ($recv =~ /\*\s*([\w\.]+)\s*$/) { $recv = $1; }
            elsif ($recv =~ /([\w\.]+)\s*$/) { $recv = $1; }
            return $recv ? "($recv).$name" : $name;
        }
        if ($l =~ /^\s*func\s+(\w+)\s*[\(<]/) {
            return $1;
        }
    }
