}

my %counts_all;
my %counts_prod;
my %callers_all;
my %callers_prod;
my %distinct_caller_funcs_all;
my %distinct_caller_funcs_prod;
my %evidence;

sub record_call {
    my ($key, $file, $line_no, $snippet, $is_test, $caller_func) = @_;
    $counts_all{$key}++;
    $callers_all{$key}{"$file:$line_no"} = 1;
    $distinct_caller_funcs_all{$key}{"$file:$caller_func"} = 1;
    if (!$is_test) {
        $counts_prod{$key}++;
        $callers_prod{$key}{"$file:$line_no"} = 1;
        $distinct_caller_funcs_prod{$key}{"$file:$caller_func"} = 1;
    }
    if (!exists $evidence{$key} || scalar(@{ $evidence{$key} }) < 8) {
        push @{ $evidence{$key} }, "$file:$line_no: $snippet";
    }
}

sub count_calls_in_file {
    my ($file) = @_;
    open my $fh, '<', $file or return;
    local $/;
    my $raw = <$fh>;
    close $fh;

    my $is_test = is_test_file($file);
