    my ($imports, $path_aliases) = parse_imports($raw);
    my $caller_pkg_path = pkg_path_from_file($file);

    my @raw_lines = split /\n/, $raw;
    my @stripped_lines = split /\n/, $stripped;

    my %aliases_for_pkg;
    for my $key (keys %decls) {
        my $d = $decls{$key};
        my $pp = $d->{pkg_path};
        my %seen;
        my @aliases;
        if ($caller_pkg_path eq $pp) {
            push @aliases, '';
            $seen{''} = 1;
        }
        if (exists $path_aliases->{$pp}) {
            for my $a (@{ $path_aliases->{$pp} }) {
                next if $seen{$a}++;
                push @aliases, $a;
            }
        }
        for my $alias (keys %$imports) {
            next unless $imports->{$alias} eq $pp;
            next if $seen{$alias}++;
            push @aliases, $alias;
        }
        $aliases_for_pkg{$key} = \@aliases if @aliases;
    }

    for my $ln (0 .. $#stripped_lines) {
        my $line = $stripped_lines[$ln];
        my $raw_line = $raw_lines[$ln] // '';
        next if $line =~ /^\s*func\s+/;

        my $caller_func = find_enclosing_func(\@stripped_lines, $ln);

        for my $key (keys %decls) {
            next unless exists $aliases_for_pkg{$key};
            my $d = $decls{$key};
            my $name = $d->{name};
            my $recv = $d->{recv};

            for my $alias (@{ $aliases_for_pkg{$key} }) {
                if ($recv eq '') {
                    if ($alias eq '') {
                        while ($line =~ /\b\Q$name\E\s*\(/g) {
                            my $pos = pos($line) - length($name) - 1;
                            my $before = $pos > 0 ? substr($line, $pos - 1, 1) : '';
                            next if $before eq '.';
                            record_call($key, $file, $ln + 1, substr($raw_line, 0, 120), $is_test, $caller_func);
                        }
                    } else {
                        while ($line =~ /\b\Q$alias\E\.\Q$name\E\s*\(/g) {
                            record_call($key, $file, $ln + 1, substr($raw_line, 0, 120), $is_test, $caller_func);
                        }
                    }
                } else {
                    while ($line =~ /\.\Q$name\E\s*\(/g) {
                        record_call($key, $file, $ln + 1, substr($raw_line, 0, 120), $is_test, $caller_func);
                    }
                }
            }
        }
    }
}

parse_internal_decls();

my @all_go;
find({
    wanted => sub {
        return unless $_ =~ /\.go$/;
        push @all_go, $File::Find::name;
    },
    no_chdir => 1,
}, $REPO);

for my $file (@all_go) {
    count_calls_in_file($file);
}

my @ranked_all = sort {
    ($counts_all{$b} // 0) <=> ($counts_all{$a} // 0) || $a cmp $b
} keys %decls;

my @ranked_prod = sort {
    ($counts_prod{$b} // 0) <=> ($counts_prod{$a} // 0) || $a cmp $b
} keys %decls;

sub print_ranked {
    my ($title, $ranked, $counts, $callers, $caller_funcs) = @_;
    print "\n=== $title ===\n";
    my $n = 0;
    for my $key (@$ranked) {
        last if $n >= 20;
        my $d = $decls{$key};
        my $c = $counts->{$key} // 0;
        next if $c == 0 && $n >= 12;
        my $site_count = scalar keys %{ $callers->{$key} // {} };
        my $func_count = scalar keys %{ $caller_funcs->{$key} // {} };
        print sprintf("%3d  %4d syntactic call sites  %3d distinct file:line sites  %3d distinct caller funcs  %s\n",
            $n + 1, $c, $site_count, $func_count, $d->{id});
        print "      decl: $d->{file}:$d->{line}  pkg=$d->{pkg_path}\n";
        if ($c > 0 && exists $evidence{$key}) {
            for my $ev (@{ $evidence{$key} }) {
                print "      -> $ev\n";
            }
        }
        $n++;
    }
}

print "Fan-in analysis for internal/ declarations\n";
print "Methodology: distinct syntactic call sites per matching line occurrence\n";
print "Total internal declarations: " . scalar(keys %decls) . "\n";
print "Total Go files scanned: " . scalar(@all_go) . "\n";

print_ranked('ALL Go files', \@ranked_all, \%counts_all, \%callers_all, \%distinct_caller_funcs_all);
print_ranked('PRODUCTION only (exclude *_test.go callers)', \@ranked_prod, \%counts_prod, \%callers_prod, \%distinct_caller_funcs_prod);

my $win_all = $ranked_all[0];
my $win_prod = $ranked_prod[0];
my $wa = $decls{$win_all};
my $wp = $decls{$win_prod};
print "\n=== WINNER ALL ===\n";
print "$wa->{id} @ $wa->{file}:$wa->{line} => " . ($counts_all{$win_all} // 0) . "\n";
print "\n=== WINNER PROD ===\n";
print "$wp->{id} @ $wp->{file}:$wp->{line} => " . ($counts_prod{$win_prod} // 0) . "\n";

