            }
            if ($n eq '*') {
                $i += 2;
                while ($i + 1 < $len && !(substr($src, $i, 1) eq '*' && substr($src, $i + 1, 1) eq '/')) {
                    $i++;
                }
                $i += 2 if $i + 1 < $len;
                next;
            }
        }
        if ($c eq '"' || $c eq '`') {
            my $quote = $c;
            $out .= $c;
