                }
                last if $ch eq $quote;
            }
            next;
        }
        if ($c eq "'" && $i + 2 < $len) {
            $out .= substr($src, $i, 3);
            $i += 3;
            next;
        }
        $out .= $c;
        $i++;
    }
    return $out;
}

