my @decl_order;

sub decl_key {
    my ($pkg_path, $recv, $name) = @_;
    $recv //= '';
    return "$pkg_path|$recv|$name";
}

sub parse_internal_decls {
    find({
        wanted => sub {
            return unless $_ =~ /\.go$/;
            return unless $File::Find::name =~ m{^\Q$REPO\E/internal/};
            my $file = $File::Find::name;
            open my $fh, '<', $file or return;
            local $/;
            my $raw = <$fh>;
            close $fh;

            my $pkg = 'unknown';
            if ($raw =~ /^package\s+(\w+)/m) {
                $pkg = $1;
            }
            my $pkg_path = pkg_path_from_file($file);
            my @lines = split /\n/, $raw;
            for my $ln (0 .. $#lines) {
                my $line = $lines[$ln];
                next unless $line =~ /^\s*func\s+/;
                my ($recv, $name);
                if ($line =~ /^\s*func\s+\(([^)]*)\)\s+(\w+)\s*[\(<]/) {
                    ($recv, $name) = ($1, $2);
                    $recv =~ s/^\s+|\s+$//g;
                    if ($recv =~ /\*\s*([\w\.]+)\s*$/) {
                        $recv = $1;
                    } elsif ($recv =~ /([\w\.]+)\s*$/) {
                        $recv = $1;
                    }
                } elsif ($line =~ /^\s*func\s+(\w+)\s*[\(<]/) {
