        $imports{$alias} = $path;
        push @{ $path_to_aliases{$path} }, $alias;
    }
    while ($raw =~ /import\s*\((.*?)\)/sg) {
        my $block = $1;
        for my $line (split /\n/, $block) {
            $line =~ s/\/\/.*$//;
            next if $line =~ /^\s*$/;
            if ($line =~ /^\s*([\w\.]+)\s+"([^"]+)"/) {
                my ($alias, $path) = ($1, $2);
                $imports{$alias} = $path;
                push @{ $path_to_aliases{$path} }, $alias;
            } elsif ($line =~ /^\s*"([^"]+)"/) {
                my $path = $1;
                my $alias = basename($path);
                $alias =~ s/-//g;
                $imports{$alias} = $path;
                push @{ $path_to_aliases{$path} }, $alias;
            }
        }
    }
    return (\%imports, \%path_to_aliases);
}

sub find_enclosing_func {
    my ($lines, $line_idx) = @_;
    for (my $i = $line_idx; $i >= 0; $i--) {
        my $l = $lines[$i];
        if ($l =~ /^\s*func\s+\(([^)]*)\)\s+(\w+)\s*[\(<]/) {
            my ($recv, $name) = ($1, $2);
            $recv =~ s/^\s+|\s+$//g;
            if ($recv =~ /\*\s*([\w\.]+)\s*$/) { $recv = $1; }
            elsif ($recv =~ /([\w\.]+)\s*$/) { $recv = $1; }
            return $recv ? "($recv).$name" : $name;
        }
        if ($l =~ /^\s*func\s+(\w+)\s*[\(<]/) {
            return $1;
        }
    }
    return '<toplevel>';
}

my %counts_all;
my %counts_prod;
my %callers_all;
my %callers_prod;
my %distinct_caller_funcs_all;
my %distinct_caller_funcs_prod;
my %evidence;

sub record_call {
    my ($key, $file, $line_no, $snippet, $is_test, $caller_func) = @_;
    $counts_all{$key}++;
    $callers_all{$key}{"$file:$line_no"} = 1;
    $distinct_caller_funcs_all{$key}{"$file:$caller_func"} = 1;
