                            record_call($key, $file, $ln+1, substr($raw_line,0,120), $is_test, $caller);
                        }
                    }
                } else {
                    # Methods: only count in files that import/are in declaring package
                    # AND for ambiguous method names, require type hint on same line if possible
                    next if $ambiguous_names{$name} && $caller_pkg_path ne $d->{pkg_path}
                        && !( $line =~ /\b\Q$recv\E/ || $line =~ /\*\Q$recv\E/ );
                    while ($line =~ /\.\Q$name\E\s*\(/g) {
                        record_call($key, $file, $ln+1, substr($raw_line,0,120), $is_test, $caller);
                    }
                }
            }
        }
    }
}

