sub print_ranked {
    my ($title, $ranked, $counts, $sites, $callers) = @_;
    print "\n=== $title ===\n";
    my $n = 0;
    for my $key (@$ranked) {
        last if $n >= 20;
        my $d = $decls{$key};
        my $c = $counts->{$key} // 0;
        next if $c == 0 && $n >= 12;
        printf "%3d  %4d call sites  %3d distinct file:line  %3d caller funcs  %s\n",
            $n+1, $c, scalar(keys %{$sites->{$key}//{}}), scalar(keys %{$callers->{$key}//{}}), $d->{id};
        print "      decl $d->{file}:$d->{line}\n";
        if ($c && $evidence{$key}) {
            for my $ev (@{ $evidence{$key} }) { print "      -> $ev\n"; }
        }
        $n++;
    }
}

